pub const SearchType = enum {
    auto,
    fast,
    deep,
    deep_reasoning,
    instant,

    pub fn toString(self: SearchType) []const u8 {
        return switch (self) {
            .auto => "auto",
            .fast => "fast",
            .deep => "deep",
            .deep_reasoning => "deep-reasoning",
            .instant => "instant",
        };
    }

    pub fn fromString(s: []const u8) ?SearchType {
        if (mem.eql(u8, s, "auto")) return .auto;
        if (mem.eql(u8, s, "fast")) return .fast;
        if (mem.eql(u8, s, "deep")) return .deep;
        if (mem.eql(u8, s, "deep-reasoning")) return .deep_reasoning;
        if (mem.eql(u8, s, "instant")) return .instant;
        return null;
    }
};

