fn jsonStringify(allocator: Allocator, value: anytype) ![]const u8 {
    var list = ArrayList(u8).init(allocator);
    errdefer list.deinit();
    try json.stringify(value, .{}, list.writer());
    return list.toOwnedSlice();
}

pub const JsonObject = struct {
    allocator: Allocator,
    entries: ArrayList(Entry),

    const Entry = struct {
        key: []const u8,
        value: JsonValue,
    };

    pub fn init(allocator: Allocator) JsonObject {
        return .{
            .allocator = allocator,
            .entries = ArrayList(Entry).init(allocator),
        };
    }

    pub fn deinit(self: *JsonObject) void {
        for (self.entries.items) |*entry| {
            entry.value.deinit(self.allocator);
        }
        self.entries.deinit();
    }

    pub fn put(self: *JsonObject, key: []const u8, value: JsonValue) !void {
        try self.entries.append(.{ .key = key, .value = value });
    }

    pub fn toJsonString(self: *const JsonObject, allocator: Allocator) ![]const u8 {
        var list = ArrayList(u8).init(allocator);
        errdefer list.deinit();
        const writer = list.writer();
        try self.writeJson(writer);
        return list.toOwnedSlice();
    }

    pub fn writeJson(self: *const JsonObject, writer: anytype) !void {
        try writer.writeByte('{');
        for (self.entries.items, 0..) |entry, i| {
            if (i > 0) try writer.writeByte(',');
            try writer.writeByte('"');
            try writer.writeAll(entry.key);
            try writer.writeByte('"');
            try writer.writeByte(':');
            try entry.value.writeJson(writer);
        }
        try writer.writeByte('}');
    }
};

pub const JsonValue = union(enum) {
    string: []const u8,
    integer: i64,
    float: f64,
    boolean: bool,
    null_val: void,
    object: JsonObject,
    array: ArrayList(JsonValue),
    raw_json: []const u8,

    pub fn deinit(self: *JsonValue, allocator: Allocator) void {
        switch (self.*) {
            .object => |*o| o.deinit(),
            .array => |*a| {
                for (a.items) |*item| {
                    item.deinit(allocator);
                }
                a.deinit();
            },
            else => {},
        }
    }

    pub fn writeJson(self: *const JsonValue, writer: anytype) !void {
        switch (self.*) {
            .string => |s| {
                try writer.writeByte('"');
                for (s) |c| {
                    switch (c) {
                        '"' => try writer.writeAll("\\\""),
                        '\\' => try writer.writeAll("\\\\"),
                        '\n' => try writer.writeAll("\\n"),
                        '\r' => try writer.writeAll("\\r"),
                        '\t' => try writer.writeAll("\\t"),
                        else => try writer.writeByte(c),
                    }
                }
                try writer.writeByte('"');
            },
            .integer => |v| {
                try fmt.formatInt(v, 10, .lower, .{}, writer);
            },
            .float => |v| {
                try fmt.formatFloatDecimal(v, .{}, writer);
            },
            .boolean => |v| {
                try writer.writeAll(if (v) "true" else "false");
            },
            .null_val => {
                try writer.writeAll("null");
            },
            .object => |*o| {
                try o.writeJson(writer);
            },
            .array => |a| {
                try writer.writeByte('[');
                for (a.items, 0..) |*item, i| {
                    if (i > 0) try writer.writeByte(',');
                    try item.writeJson(writer);
                }
                try writer.writeByte(']');
            },
            .raw_json => |r| {
                try writer.writeAll(r);
            },
        }
    }
};

fn buildJsonBody(allocator: Allocator, obj: *JsonObject) ![]const u8 {
    return obj.toJsonString(allocator);
}

fn addStringArray(allocator: Allocator, obj: *JsonObject, key: []const u8, arr: []const []const u8) !void {
    var json_arr = ArrayList(JsonValue).init(allocator);
    for (arr) |s| {
        try json_arr.append(JsonValue{ .string = s });
    }
    try obj.put(key, JsonValue{ .array = json_arr });
}

pub const Research = struct {
    client: *Exa,

    pub fn create(self: *Research, params: ResearchCreateParams) !ResearchDto {
        var obj = JsonObject.init(self.client.allocator);
        defer obj.deinit();

        try obj.put("instructions", JsonValue{ .string = params.instructions });
        try obj.put("model", JsonValue{ .string = params.model.toString() });

        if (params.output_schema) |schema| {
            _ = schema;
            try obj.put("outputSchema", JsonValue{ .null_val = {} });
        }

        const body = try buildJsonBody(self.client.allocator, &obj);
        defer self.client.allocator.free(body);

        const response_body = try self.client.doPost("/research", body);
        defer self.client.allocator.free(response_body);

        return parseResearchDto(self.client.allocator, response_body);
    }

    pub fn get(self: *Research, params: ResearchGetParams) !ResearchDto {
        var path_buf: [512]u8 = undefined;
        var query_str: []const u8 = "";
        if (params.events) {
            query_str = "?events=true";
        }
        const path = try fmt.bufPrint(&path_buf, "/research/{s}{s}", .{ params.research_id, query_str });

        const response_body = try self.client.doGet(path);
        defer self.client.allocator.free(response_body);

        return parseResearchDto(self.client.allocator, response_body);
    }

    pub fn poll_until_finished(self: *Research, params: ResearchPollParams) !ResearchDto {
        const start = std.time.milliTimestamp();
        while (true) {
            const elapsed = std.time.milliTimestamp() - start;
            if (elapsed > params.timeout_ms) {
                return error.Timeout;
            }

            const result = try self.get(.{
                .research_id = params.research_id,
                .events = params.events,
            });

            if (mem.eql(u8, result.status, "completed") or
                mem.eql(u8, result.status, "failed") or
                mem.eql(u8, result.status, "canceled"))
            {
                return result;
            }

            std.time.sleep(@intCast(params.poll_interval_ms * std.time.ns_per_ms));
        }
    }

    pub fn list(self: *Research, params: ResearchListParams) !ListResearchResponseDto {
        var path_buf: [1024]u8 = undefined;
        var query_parts = ArrayList(u8).init(self.client.allocator);
        defer query_parts.deinit();

        var has_query = false;
        if (params.cursor) |cursor| {
            if (!has_query) {
                try query_parts.appendSlice("?");
                has_query = true;
            } else {
                try query_parts.appendSlice("&");
            }
            try query_parts.appendSlice("cursor=");
            try query_parts.appendSlice(cursor);
        }
        if (params.limit) |limit| {
            if (!has_query) {
                try query_parts.appendSlice("?");
                has_query = true;
            } else {
                try query_parts.appendSlice("&");
            }
            try query_parts.appendSlice("limit=");
            var num_buf: [20]u8 = undefined;
            const num_str = try fmt.bufPrint(&num_buf, "{d}", .{limit});
            try query_parts.appendSlice(num_str);
        }

        const path = try fmt.bufPrint(&path_buf, "/research{s}", .{query_parts.items});
        const response_body = try self.client.doGet(path);
        defer self.client.allocator.free(response_body);

        return parseListResearchResponse(self.client.allocator, response_body);
    }
};

fn parseJsonValue(allocator: Allocator, input: []const u8) !json.Parsed(json.Value) {
    return json.parseFromSlice(json.Value, allocator, input, .{ .allocate = .alloc_always });
}

fn getStringField(obj: json.Value, field: []const u8) ?[]const u8 {
    if (obj != .object) return null;
    const val = obj.object.get(field) orelse return null;
    if (val == .string) return val.string;
    return null;
}

fn getFloatField(obj: json.Value, field: []const u8) ?f64 {
    if (obj != .object) return null;
    const val = obj.object.get(field) orelse return null;
    return switch (val) {
        .float => val.float,
        .integer => @as(f64, @floatFromInt(val.integer)),
        else => null,
    };
}

fn getIntField(obj: json.Value, field: []const u8) ?i64 {
    if (obj != .object) return null;
    const val = obj.object.get(field) orelse return null;
    if (val == .integer) return val.integer;
    return null;
}

fn getBoolField(obj: json.Value, field: []const u8) ?bool {
    if (obj != .object) return null;
    const val = obj.object.get(field) orelse return null;
    if (val == .bool) return val.bool;
    return null;
}

fn parseResult(obj: json.Value) Result {
    return Result{
        .url = getStringField(obj, "url") orelse "",
        .id = getStringField(obj, "id") orelse "",
        .title = getStringField(obj, "title"),
        .score = getFloatField(obj, "score"),
        .published_date = getStringField(obj, "publishedDate"),
        .author = getStringField(obj, "author"),
        .image = getStringField(obj, "image"),
        .favicon = getStringField(obj, "favicon"),
        .text = getStringField(obj, "text"),
        .summary = getStringField(obj, "summary"),
    };
}

fn parseAnswerResult(obj: json.Value) AnswerResult {
    return AnswerResult{
        .id = getStringField(obj, "id") orelse "",
        .url = getStringField(obj, "url") orelse "",
        .title = getStringField(obj, "title"),
        .published_date = getStringField(obj, "publishedDate"),
        .author = getStringField(obj, "author"),
        .text = getStringField(obj, "text"),
    };
}

fn parseResultsArray(allocator: Allocator, val: json.Value) ![]const Result {
    if (val != .array) return &[_]Result{};
    var list = ArrayList(Result).init(allocator);
    for (val.array.items) |item| {
        try list.append(parseResult(item));
    }
    return list.toOwnedSlice();
}

fn parseAnswerResultsArray(allocator: Allocator, val: json.Value) ![]const AnswerResult {
    if (val != .array) return &[_]AnswerResult{};
    var list = ArrayList(AnswerResult).init(allocator);
    for (val.array.items) |item| {
        try list.append(parseAnswerResult(item));
    }
    return list.toOwnedSlice();
}

fn parseSearchResponse(allocator: Allocator, body: []const u8) !SearchResponse {
    const parsed = try parseJsonValue(allocator, body);
    defer parsed.deinit();
    const root = parsed.value;

    const results_val = if (root == .object) root.object.get("results") orelse json.Value{ .array = .{} } else json.Value{ .array = .{} };
    const results = try parseResultsArray(allocator, results_val);

    return SearchResponse{
        .results = results,
        .autoprompt_string = getStringField(root, "autopromptString"),
        .resolved_search_type = getStringField(root, "resolvedSearchType"),
        .auto_date = getStringField(root, "autoDate"),
        .context = getStringField(root, "context"),
        .request_id = getStringField(root, "requestId"),
    };
}

fn parseAnswerResponse(allocator: Allocator, body: []const u8) !AnswerResponse {
    const parsed = try parseJsonValue(allocator, body);
    defer parsed.deinit();
    const root = parsed.value;

    const citations_val = if (root == .object) root.object.get("citations") orelse json.Value{ .array = .{} } else json.Value{ .array = .{} };
    const citations = try parseAnswerResultsArray(allocator, citations_val);

    return AnswerResponse{
        .answer = getStringField(root, "answer") orelse "",
        .citations = citations,
    };
}

fn parseResearchDto(allocator: Allocator, body: []const u8) !ResearchDto {
    const parsed = try parseJsonValue(allocator, body);
    defer parsed.deinit();
    const root = parsed.value;

    var output: ?ResearchOutput = null;
    if (root == .object) {
        if (root.object.get("output")) |output_val| {
            if (output_val == .object) {
                output = ResearchOutput{
                    .content = getStringField(output_val, "content") orelse "",
                };
            } else if (output_val == .string) {
